package zw.ac.uz.emhare.assessmentresults.result;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.SQLRestriction;import org.hibernate.envers.Audited;import zw.ac.uz.emhare.assessmentresults.assessment.*;import zw.ac.uz.emhare.common.persistence.AuditableEntity;
/** @author Tinashe K */
@Audited @Entity @Table(name="result_batches") @SQLRestriction("deleted_at IS NULL")
public class ResultBatch extends AuditableEntity{
 public enum Status{DRAFT,SUBMITTED,MODERATED,APPROVED,PUBLISHED,REJECTED}
 @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="module_offering_id")private AssessmentModuleOffering moduleOffering;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="calculation_run_id")private AssessmentCalculationRun calculationRun;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="grading_scheme_id")private GradingScheme gradingScheme;@Column(name="batch_number",nullable=false,length=50)private String batchNumber;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="status_reason",nullable=false,length=1000)private String statusReason;@Column(name="submitted_by_user_id")private UUID submittedByUserId;@Column(name="submitted_at")private Instant submittedAt;@Column(name="moderated_by_user_id")private UUID moderatedByUserId;@Column(name="moderated_at")private Instant moderatedAt;@Column(name="approved_by_user_id")private UUID approvedByUserId;@Column(name="approved_at")private Instant approvedAt;@Column(name="published_by_user_id")private UUID publishedByUserId;@Column(name="published_at")private Instant publishedAt;
 protected ResultBatch(){}public ResultBatch(AssessmentCalculationRun run,GradingScheme grading,String number){moduleOffering=run.getModuleOffering();calculationRun=run;gradingScheme=grading;batchNumber=number;status=Status.DRAFT;statusReason="Result batch materialised from a completed calculation run.";}
 public Status submit(UUID actor,String reason,Instant now,long expected){version(expected);require(Status.DRAFT);Status old=status;status=Status.SUBMITTED;statusReason=text(reason);submittedByUserId=actor;submittedAt=now;return old;}public Status moderate(UUID actor,String reason,Instant now,long expected){version(expected);require(Status.SUBMITTED);if(actor.equals(submittedByUserId))throw new IllegalStateException("The submitter cannot moderate the same result batch.");Status old=status;status=Status.MODERATED;statusReason=text(reason);moderatedByUserId=actor;moderatedAt=now;return old;}public Status approve(UUID actor,String reason,Instant now,long expected){version(expected);require(Status.MODERATED);if(actor.equals(moderatedByUserId))throw new IllegalStateException("The moderator cannot approve the same result batch.");Status old=status;status=Status.APPROVED;statusReason=text(reason);approvedByUserId=actor;approvedAt=now;return old;}public Status publish(UUID actor,String reason,Instant now,long expected){version(expected);require(Status.APPROVED);Status old=status;status=Status.PUBLISHED;statusReason=text(reason);publishedByUserId=actor;publishedAt=now;return old;}
 private void version(long value){if(getVersion()!=value)throw new IllegalStateException("Result batch changed. Refresh before retrying.");}private void require(Status required){if(status!=required)throw new IllegalStateException("Result batch is not at the required workflow stage.");}private static String text(String value){return GradingScheme.text(value);}
 public AssessmentModuleOffering getModuleOffering(){return moduleOffering;}public AssessmentCalculationRun getCalculationRun(){return calculationRun;}public GradingScheme getGradingScheme(){return gradingScheme;}public String getBatchNumber(){return batchNumber;}public Status getStatus(){return status;}public String getStatusReason(){return statusReason;}public UUID getSubmittedByUserId(){return submittedByUserId;}public Instant getSubmittedAt(){return submittedAt;}public UUID getModeratedByUserId(){return moderatedByUserId;}public Instant getModeratedAt(){return moderatedAt;}public UUID getApprovedByUserId(){return approvedByUserId;}public Instant getApprovedAt(){return approvedAt;}public UUID getPublishedByUserId(){return publishedByUserId;}public Instant getPublishedAt(){return publishedAt;}
}
